# AI Office v1.7 Part C Dashboard, Certification, and Release Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\financial-office",
 "workspace\financial-office\certification",
 "dashboard\public",
 "scripts\financial-office",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\financial-office\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\financial-office\New-AIOfficeFinancialDashboardSnapshot.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\financial-office-module.js" -Base64Content ""
Write-EmbeddedFile -RelativePath "dashboard\public\financial-office-module.css" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\financial-office\Install-AIOfficeFinancialDashboardIntegration.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\financial-office\Test-AIOfficeFinancialDashboard.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\financial-office\Certify-AIOfficeFinancialOffice.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\financial-office\Publish-AIOfficeFinancialOfficeRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\financial-office\Test-AIOfficeFinancialOffice.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.7-Release-Notes.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v1.7-Part-C-Dashboard-Certification-Release.md" -Base64Content ""
$Scripts = Get-ChildItem -LiteralPath "E:\AI\AI-Office\scripts\financial-office" -Filter "*.ps1" -File
foreach ($Script in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script.FullName + ": " + (($ParseErrors | ForEach-Object {$_.Message}) -join "; ")) }
}
Get-Content -LiteralPath "E:\AI\AI-Office\config\financial-office\release-manifest.json" -Raw | ConvertFrom-Json | Out-Null
& "E:\AI\AI-Office\scripts\financial-office\Install-AIOfficeFinancialDashboardIntegration.ps1"
$VersionPath = "E:\AI\AI-Office\config\identity\version.json"
if (Test-Path -LiteralPath $VersionPath -PathType Leaf) {
 $Version = Get-Content -LiteralPath $VersionPath -Raw | ConvertFrom-Json
 $Version.version = "1.7.0"
 $Version.release_name = "Personal Financial Office"
 $Version.status = "part_c_installed"
 $Version.installed_at = (Get-Date).ToString("o")
 $Version.next_planned_milestone = "1.8 Business Incubator"
 $Version | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath $VersionPath -Encoding UTF8
}
Write-Host ""
Write-Host "AI Office v1.7 Part C Dashboard, Certification, and Release installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan